import { productVisibleForPostal, storeVisibleForPostal } from './delivery-context.js';
export function renderConfiguredModules(modules,products,card,escape){return modules.map((m,i)=>{const targetProduct=m.target?.match(/^#\/produto\/(\d+)/)?.[1],targetStore=m.target?.match(/^#\/loja\/(\d+)/)?.[1];if(targetProduct&&!productVisibleForPostal(products.find(p=>p.id===Number(targetProduct))))return '';if(targetStore&&!storeVisibleForPostal(Number(targetStore)))return '';const list=(m.ids?.length?m.ids.map(id=>products.find(p=>p.id===id)).filter(Boolean):products).filter(p=>productVisibleForPostal(p)).slice(0,m.count||10);if(!list.length)return '';if(m.type==='categories'){const categories=[...new Set(list.map(p=>p.category))];return `<section class="section configured-module"><h2>${escape(m.title)}</h2><nav class="store-categories" aria-label="Categorias">${categories.map(c=>`<a href="#/loja/${list[0].store}?category=${encodeURIComponent(c)}">${escape(c)}</a>`).join('')}</nav></section>`;}if(m.type==='grid')return `<section class="section configured-module"><h2>${escape(m.title)}</h2><div class="listing-grid related-grid">${list.map(card).join('')}</div></section>`;if(m.type==='showcase')return `<section class="section configured-module"><div class="section-head"><h2>${escape(m.title)}</h2><div><button data-config-scroll="-1" aria-label="Produtos anteriores">←</button><button data-config-scroll="1" aria-label="Próximos produtos">→</button></div></div><div class="products carousel-track" tabindex="0" aria-label="${escape(m.title)}">${list.map(card).join('')}</div></section>`;const tiles=m.type==='mosaic'?list.slice(0,4):[list[0]];return `<section class="section configured-module"><h2>${escape(m.title)}</h2><div class="${m.type==='mosaic'?'configured-mosaic':'configured-banner'}">${tiles.map((p,index)=>{const custom=m.type==='mosaic'?m.images?.[index]:m.image,src=custom&&/^https:\/\//.test(custom)?custom:p.image,target=/^#\/(busca|produto\/\d+|loja\/\d+)/.test(m.target)?m.target:'#/produto/'+p.id;return `<a href="${escape(m.type==='mosaic'?'#/produto/'+p.id:target)}"><img src="${escape(src)}" alt="${escape(m.type==='mosaic'?p.name:m.title)}"><span>${escape(m.type==='mosaic'?p.name:m.title)} →</span></a>`}).join('')}</div></section>`}).join('')}
export function bindConfiguredCarousels(root=document){root.querySelectorAll('[data-config-scroll]').forEach(b=>b.onclick=()=>{const track=b.closest('.configured-module').querySelector('.carousel-track');track.scrollBy({left:Number(b.dataset.configScroll)*track.clientWidth,behavior:'smooth'})})}
